field_before:
selectable = {
	custom_trigger_tooltip = {
		tooltip = eon_defensive_alliance_offer_terms_available_tt
		eon_defensive_alliance_offer_terms_available = yes
	}
	custom_trigger_tooltip = {
		tooltip = eon_defensive_alliance_offer_no_pending_tt
		eon_defensive_alliance_offer_no_pending = yes
	}
}

field_after:
selectable = {
	OR = {
		AND = {
			custom_trigger_tooltip = {
				tooltip = eon_defensive_alliance_offer_terms_available_tt
				eon_defensive_alliance_offer_terms_available = yes
			}
			custom_trigger_tooltip = {
				tooltip = eon_defensive_alliance_offer_no_pending_tt
				eon_defensive_alliance_offer_no_pending = yes
			}
		}
		AND = {
			# Keep an AI recipient's reserved response selectable; send/consent gates stay strict.
			is_ai = yes
			eon_defensive_alliance_offer_response_current = yes
		}
	}
}
